  `special_bonus1` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '必杀特殊加成1描述',
  `special_bonus2` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '必杀特殊加成2描述',
  `special_bonus1_lv` int NULL DEFAULT NULL COMMENT '必杀特殊加成1触发等级',
